PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,password_iterations INTEGER NOT NULL DEFAULT 240000);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires TEXT NOT NULL,last_activity TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,generic TEXT,brand TEXT,manufacturer TEXT,supplier TEXT,sku TEXT UNIQUE,barcode TEXT UNIQUE,category TEXT,strength TEXT,form TEXT,pack_size INTEGER NOT NULL DEFAULT 1,cost INTEGER NOT NULL,price INTEGER NOT NULL,reorder INTEGER NOT NULL,location TEXT,rx INTEGER NOT NULL DEFAULT 0,restricted TEXT DEFAULT 'none');
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),number TEXT NOT NULL,expiry TEXT NOT NULL,received INTEGER NOT NULL,quantity INTEGER NOT NULL,cost INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'available',CHECK(quantity>=0));
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT,phone TEXT,address TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL,kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rates(id TEXT PRIMARY KEY,currency TEXT NOT NULL,rate TEXT NOT NULL,effective TEXT NOT NULL,source TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,number TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,date TEXT NOT NULL,customer_id TEXT REFERENCES customers(id),supplier TEXT,currency TEXT NOT NULL,rate TEXT NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL DEFAULT 0,tax INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,base_total INTEGER NOT NULL,paid INTEGER NOT NULL DEFAULT 0,cost INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),due TEXT,reference TEXT,category TEXT,parent_id TEXT REFERENCES documents(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lines(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),product_id TEXT NOT NULL REFERENCES products(id),batch_id TEXT NOT NULL REFERENCES batches(id),quantity INTEGER NOT NULL,price INTEGER NOT NULL,cost INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,document_id TEXT REFERENCES documents(id),account_id TEXT NOT NULL REFERENCES accounts(id),date TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL,rate TEXT NOT NULL,base_amount INTEGER NOT NULL,method TEXT NOT NULL,direction TEXT NOT NULL,reference TEXT);
CREATE TABLE IF NOT EXISTS movements(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),batch_id TEXT NOT NULL REFERENCES batches(id),document_id TEXT REFERENCES documents(id),date TEXT NOT NULL,quantity INTEGER NOT NULL,reason TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS journals(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,date TEXT NOT NULL,account TEXT NOT NULL,debit INTEGER NOT NULL DEFAULT 0,credit INTEGER NOT NULL DEFAULT 0,CHECK(debit>=0 AND credit>=0));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,device TEXT NOT NULL,kind TEXT NOT NULL,event_time TEXT NOT NULL,received_time TEXT NOT NULL,status TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,date TEXT NOT NULL,action TEXT NOT NULL,source_id TEXT,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,number TEXT UNIQUE NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,date TEXT NOT NULL,cost INTEGER NOT NULL,currency TEXT NOT NULL,rate TEXT NOT NULL,location TEXT,custodian TEXT,condition TEXT,life INTEGER NOT NULL,residual INTEGER NOT NULL,disposed TEXT,proceeds INTEGER DEFAULT 0,notes TEXT);
CREATE TABLE IF NOT EXISTS tills(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),opened TEXT NOT NULL,closed TEXT,opening INTEGER NOT NULL,expected INTEGER,counted INTEGER,variance INTEGER,user_id TEXT NOT NULL REFERENCES users(id));
CREATE INDEX IF NOT EXISTS documents_date ON documents(date);
CREATE INDEX IF NOT EXISTS batch_fefo ON batches(product_id,expiry);
CREATE INDEX IF NOT EXISTS journal_source ON journals(source_id);
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,fingerprint TEXT UNIQUE NOT NULL,dataset TEXT NOT NULL,filename TEXT NOT NULL,row_count INTEGER NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_throttle(bucket TEXT PRIMARY KEY,window_start INTEGER NOT NULL,attempts INTEGER NOT NULL);
